55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
64	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String address = normalizeAddress(owner.getAddress());
115	        if (address.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setAddress(address);
119	        if (owner.getEmail() != null) {
120	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
121	            if (!EMAIL_PATTERN.matcher(email).matches()) {
122	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	            }
124	            owner.setEmail(email);
125	        }
126	        String telephone = normalizeTelephone(owner.getTelephone());
127	        if (telephone == null) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        owner.setTelephone(telephone);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        if (countOwnersRegisteredOn(LocalDate.now()) >= 100) {
135	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
136	        }
137	        if (isTelephoneInUse(telephone)) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        if (countOwnersInCity(owner.getCity()) >= 50) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
147	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
148	        owner.setHouseholdId(householdId(owner));
149	        owner.setNamesakeCount(countNamesakes(owner));
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        headers.setLocation(UriComponentsBuilder.newInstance()
153	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
154	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
160	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
161	        if (currentOwner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        currentOwner.setAddress(ownerFieldsDto.getAddress());
165	        currentOwner.setCity(ownerFieldsDto.getCity());
166	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
167	        currentOwner.setLastName(ownerFieldsDto.getLastName());
168	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
169	        String email = ownerFieldsDto.getEmail();
170	        if (email != null) {
171	            email = email.trim().toLowerCase(Locale.ROOT);
172	            if (!EMAIL_PATTERN.matcher(email).matches()) {
173	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	            }
175	        }
176	        currentOwner.setEmail(email);
177	        this.clinicService.saveOwner(currentOwner);
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Transactional
183	    @Override
184	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        this.clinicService.deleteOwner(owner);
190	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        HttpHeaders headers = new HttpHeaders();
201	        Pet pet = petMapper.toPet(petFieldsDto);
202	        owner.setId(ownerId);
203	        pet.setOwner(owner);
204	        pet.getType().setName(null);
205	        this.clinicService.savePet(pet);
206	        PetDto petDto = petMapper.toPetDto(pet);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
208	            .buildAndExpand(pet.getId()).toUri());
209	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
215	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
216	        if (currentOwner != null) {
217	            Pet currentPet = this.clinicService.findPetById(petId);
218	            if (currentPet != null) {
219	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
220	                currentPet.setName(petFieldsDto.getName());
221	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
222	                this.clinicService.savePet(currentPet);
223	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
232	        HttpHeaders headers = new HttpHeaders();
233	        Visit visit = visitMapper.toVisit(visitFieldsDto);
234	        Pet pet = new Pet();
235	        pet.setId(petId);
236	        visit.setPet(pet);
237	        this.clinicService.saveVisit(visit);
238	        VisitDto visitDto = visitMapper.toVisitDto(visit);
239	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
240	            .buildAndExpand(visit.getId()).toUri());
241	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
242	    }
243	
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner != null) {
250	            Pet pet = owner.getPet(petId);
251	            if (pet != null) {
252	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
259	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
260	
261	    /**
262	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
263	     * code are kept when present; otherwise country code '+61' is assumed and a single
264	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
265	     * stripped. The result must be a '+' followed by 8 to 15 digits.
266	     * Returns {@code null} when the number cannot form a valid E.164 value.
267	     */
268	    private static String normalizeTelephone(String telephone) {
269	        if (telephone == null) {
270	            return null;
271	        }
272	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
273	        String e164;
274	        if (cleaned.startsWith("+")) {
275	            e164 = cleaned;
276	        } else {
277	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
278	            e164 = "+61" + national;
279	        }
280	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
281	    }
282	
283	    /**
284	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
285	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
286	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
287	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
288	     */
289	    private String generateCustomerCode(String city, String lastName) {
290	        String city3 = firstThreeLetters(city);
291	        String last3 = firstThreeLetters(lastName);
292	        int sequence = countOwnersInCity(city) + 1;
293	        return String.format("%s-%s-%04d", city3, last3, sequence);
294	    }
295	
296	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
297	    private static String firstThreeLetters(String value) {
298	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
299	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
300	    }
301	
302	    /**
303	     * The number of existing owners registered in {@code city}, compared case-insensitively
304	     * with collapsed whitespace.
305	     */
306	    private int countOwnersInCity(String city) {
307	        String normalized = normalizeHouseholdField(city);
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
310	            .count();
311	    }
312	
313	    /**
314	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
315	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
316	     */
317	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
318	        String yy = String.format("%02d", registrationDate.getYear() % 100);
319	        return customerCode + "-M" + yy;
320	    }
321	
322	    /**
323	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
324	     * last name, compared case-insensitively.
325	     */
326	    private int countNamesakes(Owner owner) {
327	        String firstName = normalizeHouseholdField(owner.getFirstName());
328	        String lastName = normalizeHouseholdField(owner.getLastName());
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
331	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
332	            .count();
333	    }
334	
335	    /** The number of existing owners whose registration date is {@code date}. */
336	    private int countOwnersRegisteredOn(LocalDate date) {
337	        return (int) this.clinicService.findAllOwners().stream()
338	            .filter(existing -> date.equals(existing.getRegistrationDate()))
339	            .count();
340	    }
341	
342	    /** Whether any existing owner already uses the given (E.164) telephone number. */
343	    private boolean isTelephoneInUse(String telephone) {
344	        return this.clinicService.findAllOwners().stream()
345	            .map(Owner::getTelephone)
346	            .filter(existing -> existing != null)
347	            .map(OwnerRestControllerV1::normalizeTelephone)
348	            .filter(existing -> existing != null)
349	            .anyMatch(telephone::equals);
350	    }
351	
352	    /** Common street-type abbreviations expanded during address normalization. */
353	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
354	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
355	
356	    /**
357	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
358	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
359	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
360	     * string when {@code address} is null or blank after normalization.
361	     */
362	    private static String normalizeAddress(String address) {
363	        if (address == null) {
364	            return "";
365	        }
366	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
367	        if (collapsed.isEmpty()) {
368	            return "";
369	        }
370	        StringBuilder sb = new StringBuilder(collapsed.length());
371	        for (String token : collapsed.split(" ")) {
372	            if (sb.length() > 0) {
373	                sb.append(' ');
374	            }
375	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
376	        }
377	        return sb.toString();
378	    }
379	
380	    /**
381	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
382	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
383	     */
384	    private static String normalizeHouseholdField(String value) {
385	        if (value == null) {
386	            return "";
387	        }
388	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
389	    }
390	
391	    /**
392	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
393	     * same address compared case-insensitively with collapsed whitespace.
394	     */
395	    private List<Owner> findHousemates(Owner owner) {
396	        String lastName = normalizeHouseholdField(owner.getLastName());
397	        String address = normalizeHouseholdField(owner.getAddress());
398	        return this.clinicService.findAllOwners().stream()
399	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
400	                && normalizeHouseholdField(existing.getAddress()).equals(address))
401	            .toList();
402	    }
403	
404	    /**
405	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
406	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
407	     */
408	    private boolean isHouseholdInUse(Owner owner) {
409	        return !findHousemates(owner).isEmpty();
410	    }
411	
412	    /**
413	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
414	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
415	     * deterministically from those normalized fields so housemates always resolve to the same value,
416	     * regardless of registration order.
417	     */
418	    private static String householdId(Owner owner) {
419	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
420	            + normalizeHouseholdField(owner.getAddress());
421	        try {
422	            byte[] digest = MessageDigest.getInstance("SHA-256")
423	                .digest(key.getBytes(StandardCharsets.UTF_8));
424	            StringBuilder sb = new StringBuilder(24);
425	            for (int i = 0; i < 12; i++) {
426	                sb.append(String.format("%02X", digest[i]));
427	            }
428	            return sb.toString();
429	        }
430	        catch (NoSuchAlgorithmException e) {
431	            throw new IllegalStateException("SHA-256 not available", e);
432	        }
433	    }
434	}
